CREATE TABLE IF NOT EXISTS payment_orders(id uuid PRIMARY KEY,venue_id uuid NOT NULL REFERENCES venues,customer_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL DEFAULT 'INR',provider_order_id text UNIQUE,provider_payment_id text UNIQUE,status text NOT NULL DEFAULT 'Creating',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(venue_id,customer_id) REFERENCES customers(venue_id,id));
CREATE TABLE IF NOT EXISTS provider_events(event_id text PRIMARY KEY,provider_payment_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS automation_deliveries(event_id uuid PRIMARY KEY REFERENCES outbox,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,last_error text);
CREATE TABLE IF NOT EXISTS handover_notes(id uuid PRIMARY KEY,venue_id uuid NOT NULL REFERENCES venues,body text NOT NULL,priority text NOT NULL DEFAULT 'Normal',actor text NOT NULL,resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents(id uuid PRIMARY KEY,venue_id uuid NOT NULL REFERENCES venues,station_id text,customer_id uuid,title text NOT NULL,minutes_lost integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'Open',credit_minor bigint NOT NULL DEFAULT 0,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
